#include <iostream>
#include <vector>
using namespace std;

long long fast_power(long long base, int exponent, int modulus) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exponent >>= 1;
    }
    return result;
}

int main() {
    int p, k;
    cin >> p >> k;
    if (k == 0) {
        cout << fast_power(p, p - 1, 1000000007) << endl;
        return 0;
    }
    if (k == 1) {
        cout << fast_power(p, p, 1000000007) << endl;
        return 0;
    }
    vector<bool> visited(p + 1, false);
    int cycle_length = 1;
    long long current = k;
    visited[1] = true;
    while (!visited[current]) {
        visited[current] = true;
        current = (current * k) % p;
        cycle_length++;
    }
    long long total_power = (p - 1) / cycle_length;
    cout << fast_power(p, total_power, 1000000007) << endl;
    return 0;
}
